# ptfix plug-in of agent lbdaosi (2026-10-04): "Lenh Bai Dao Si" (61480), "Lenh Bai Di Nhan" (61481), "Lenh Bai Giap Si" (61482, r3).
# Server + Client: settings\item\001\magicscript.txt gets THREE rows (genre 6, detail 1, particular 61480 / 61481 / 61482):
#   permanent, never consumed (the scripts never remove them), stack 1, no drop / trade / gamble / stall / sell,
#   scripts \script\phongthan\item\lbdaosi_lenhbai.lua / lbdinhan_lenhbai.lua (loose ASCII files generated by
#   scratchpad\lbdaosi\gen.py). The chosen skill sets live in tasks 2613 / 2614 and are read by the client auto fight.
# Columns cloned from the token row 61003 (build_ptfix.py TOKENS) or VNG 7308. Sprites: the VNG "Ky Nang Quyen" of the
# profession (row 5625 Dao Si / 5626 Di Nhan), falling back to row 1439 "Sat Ma Mat Lenh" / the template when the
# sprite is missing from this side's PAKs.
# Idempotent: adds a row only if its particular is missing; patches on top of ctx["entries"] (other plug-ins'
# magicscript rows are kept). Doc: docs\features\lenh-bai-dao-si-phong-than-20261004.md
import os

SCRIPT_DS = "\\script\\phongthan\\item\\lbdaosi_lenhbai.lua"
SCRIPT_DN = "\\script\\phongthan\\item\\lbdinhan_lenhbai.lua"
SCRIPT_GS = "\\script\\phongthan\\item\\lbgiapsi_lenhbai.lua"
TOKENS = [
    (61480, "Lệnh Bài Đạo Sĩ",
     "Đạo Sĩ nhấp phải: bắt đầu, dừng tự động đánh; chọn bộ chiêu luân phiên theo hệ Thổ, Hỏa, Băng, Lôi hoặc bật, tắt "
     "từng chiêu (cả buff hệ); nâng cấp kỹ năng phái lên tối đa. Dùng vĩnh viễn, không mất.", SCRIPT_DS, (b"5625", b"1439")),
    (61481, "Lệnh Bài Dị Nhân",
     "Dị Nhân nhấp phải: bắt đầu, dừng tự động đánh; chọn hào quang, Bổ Tâm Chú, chú nguyền để tự đánh tự duy trì "
     "luân phiên; nâng cấp kỹ năng phái lên tối đa. Dùng vĩnh viễn, không mất.", SCRIPT_DN, (b"5626", b"1439")),
    (61482, "Lệnh Bài Giáp Sĩ",
     "Giáp Sĩ nhấp phải: bắt đầu, dừng tự động đánh; chọn bộ chiêu đoản đao, trường đao luân phiên (tự lọc theo đao "
     "đang cầm), hào quang; nâng cấp kỹ năng phái lên tối đa. Dùng vĩnh viễn, không mất.", SCRIPT_GS, (b"5624", b"1439")),
]


def _get(ctx, path):
    eid = ctx["h"](path)
    b = ctx["entries"].get(eid)
    if b is None:
        n, ent = ctx["effective"](eid)
        if not ent:
            return eid, None
        b = ctx["read_entry"](os.path.join(ctx["DATA"], n), ent)
    return eid, b


def _row(lines, key):
    for l in lines[1:]:
        c = l.rstrip(b"\r").split(b"\t")
        if len(c) > 3 and c[3] == key:
            return c
    return None


def apply(ctx):
    log = []
    eid, b = _get(ctx, "\\settings\\item\\001\\magicscript.txt")
    if b is None:
        ctx["log"]["lbdaosi"] = ["ERROR magicscript.txt missing"]
        return
    nl = b"\r\n" if b"\r\n" in b else b"\n"
    lines = b.rstrip(b"\r\n").split(nl)
    tc = ctx["tcvn"]
    added = 0
    for key, name, desc, script, sprite_rows in TOKENS:
        if _row(lines, str(key).encode()):
            log.append("already %d" % key)
            continue
        tpl = _row(lines, b"61003") or _row(lines, b"7308")
        ncol = max(34, len(tpl))
        tpl = tpl + [b""] * (ncol - len(tpl))
        c = list(tpl)
        spr = tpl[4]
        for sr in sprite_rows:
            r = _row(lines, sr)
            if not r or len(r) <= 4 or not r[4]:
                continue
            sid = ctx["h"](r[4].decode("gbk"))
            n, ent = ctx["effective"](sid)
            if ent or sid in ctx["entries"]:
                spr = r[4]
                break
            log.append("sprite of %s not in %s paks" % (sr.decode(), ctx["SIDE"]))
        c[0] = b"#<c=orange>" + tc(name) + b"<c>"
        c[1], c[2], c[3] = b"6", b"1", str(key).encode()
        c[4] = spr
        c[5], c[6], c[7] = b"39", b"1", b"1"
        c[8] = b"#" + tc(desc)
        c[9] = b""
        c[10] = b"1"
        c[12] = b"1"                          # stack 1
        c[13] = b"0"
        c[14] = script.encode("ascii")
        c[23] = b"0"                          # never consumed by the engine (the script does not remove it)
        c[24] = c[25] = c[26] = c[27] = b"0"  # no drop / trade / gamble / stall
        c[28] = b"0"                          # no PK drop
        c[29] = b""                           # permanent
        c[30] = b"0"                          # cannot sell to shop
        lines.append(b"\t".join(c[:ncol]))
        added += 1
        log.append("magicscript +%d sprite %s" % (key, spr.decode("gbk", "replace")))
    if added:
        ctx["entries"][eid] = nl.join(lines) + nl
    ctx["log"]["lbdaosi"] = log
